  dict(kicker="80.8", title="Assembler sans tout écrire", sub="cadres et briques ouvertes", scene="cadres", body=L("<b>Silero VAD</b> : détecte la voix en quelques millisecondes sur CPU.", "<b>Smart Turn</b> (Pipecat) ou le <b>turn-detector</b> de LiveKit : prédisent la fin de tour à partir de l’audio ou du texte.", "<b>Pipecat</b>, <b>LiveKit Agents</b> : chaînes STT-LLM-TTS en flux, interruption gérée.", "<b>Unmute</b> (Kyutai) : voix naturelle autour de n’importe quel LLM compatible OpenAI.", "<b>Home Assistant</b> (Wyoming : Whisper, Piper, mot de réveil) et <b>Open WebUI</b> (mode appel).") + "<p>L’<b>annulation d’écho</b> est indispensable avec un haut-parleur : sinon l’agent s’entend et s’interrompt lui-même. Le navigateur la fournit (WebRTC) ; sinon, un casque.</p>"),
  dict(kicker="80.9", title="Deux configurations types", sub="tout en local", scene="latence", body=L("<b>PC avec GPU de 16 à 24 Go</b> : faster-whisper turbo (int8) ou Parakeet ; LLM de 8 à 14 milliards en 4 bits (llama.cpp, vLLM, Ollama) ; Kyutai TTS, Chatterbox ou Kokoro ; index du RAG en mémoire. Viser 600 à 900 ms.", "<b>Mini-PC ou Raspberry Pi 5</b> : Vosk ou whisper.cpp (base, small) ; LLM de 1 à 4 milliards ; Piper. Compter une à trois secondes.", "<b>Mac à puce Apple</b> : whisper.cpp ou MLX, LLM via llama.cpp ou MLX, Kokoro.") + "<p>Le maillon le plus lent est presque toujours le <b>premier jeton du LLM</b> : un modèle plus petit et un prompt stable (cache, chapitre 3) rapportent plus qu’un STT plus rapide.</p>"),
  dict(kicker="80.10", title="Régler la détection et les tours", sub="le réglage qui change tout", scene="naturel", body=L("<b>VAD</b> (Silero) : seuil ≈ 0,5 ; ignorer les sons de moins de 250 ms (toux, clic).", "<b>Fin de tour</b> : détecteur sémantique, silence de secours de 500 à 800 ms.", "<b>Interruption</b> : couper après 300 à 500 ms de parole, pas sur un « mm ».", "<b>Après interruption</b> : ne garder dans l’historique que la partie <b>réellement prononcée</b>.") + "<p>Trop court, il coupe la parole ; trop long, il paraît lent.</p>"),
