  dict(kicker="80.12", title="Régler le LLM pour l’oral", sub="écrire pour l’oreille", scene="ragvocal", body=L("<b>Réponses courtes</b> : 150 à 250 jetons au plus ; une première phrase brève, que la synthèse lit tout de suite.", "<b>Température</b> 0,6 à 0,7 : naturel sans dérive.", "<b>Prompt stable en tête</b>, passages du RAG après : le cache reste valide d’un tour à l’autre.", "<b>Historique</b> : les derniers échanges, résumés au-delà.") + CODE("Tu parles à voix haute avec Léa. Réponds en une à trois phrases courtes, comme à l’oral. Pas de listes, de titres, d’émojis ni de liens. Écris les nombres comme on les dit. Appuie-toi sur les extraits fournis et cite leur source simplement (« d’après ta fiche du 12 mars »). Si les extraits ne répondent pas, dis-le et propose de chercher autrement. Si la question est ambiguë, pose une seule question.")),
  dict(kicker="80.13", title="Régler la synthèse", sub="naturel et sans faux pas", scene="tts", body=L("<b>Découper</b> le flux du LLM aux points, ou à la première virgule si la phrase est longue, et synthétiser morceau par morceau.", "<b>Normaliser</b> avant la synthèse : nombres, dates, unités, sigles, symboles ; supprimer le Markdown et les URL.", "<b>Lexique</b> : la prononciation des noms propres et du jargon du corpus.", "<b>Vitesse</b> 1,0 à 1,1 ; Piper : <code>length_scale</code> 0,9 à 1,0 ; Chatterbox : <code>exaggeration</code> ≈ 0,5, <code>cfg_weight</code> ≈ 0,5, plus bas pour un débit plus posé.") + "<p>Choisir une voix <b>native</b> en français : une voix anglaise qui lit du français garde un accent.</p>"),
